'use strict';

// Dependencies
var Argr = require('argr');
var _ = require('lodash');

// Configuration
var pkg = require(__dirname+'/../package.json');

var Server = require('./server');

// Command-line Interface
var argr = Argr()

  // TODO flush out better options
  .option(['l', 'disable-livereload'], 'Disables LiveReload automatic browser refresh')
  .option(['w', 'disable-watch'], 'Disables watch')

  .option(['q', 'quiet'], 'Quiet mode');

// CLI Initialize
argr.init(process.argv);

// Debugging
process.env.QUIET = argr.get('quiet');
var debug = require('./debug')(process.env.QUIET === 'true');

// Serve
Server({
  port: process.env.PORT
})
  .use(require('./routes/static')())
  .use(require('./routes/notfound')())
  .start();
